#!/usr/bin/env python3
"""Entry point:
    python industry.py recipe <Product or Blueprint name> --sde <SDE directory>
        [--material-efficiency/-me <0-10>] [--time-efficiency/-te <even 0-20>] [--display-waste/-waste]
    python industry.py invention <Product or Blueprint name> --sde <SDE directory> [--skill <1-5>]
    python industry.py plan <Build string> --config <YAML config> --sde <SDE directory> --output <dir>
        [--build-all]
"""

import sys

from eve_industry.cli import main

if __name__ == "__main__":
    sys.exit(main())
"""Command-line interface."""

import argparse
import sys
from pathlib import Path
from typing import List, Optional

from .industry_data import IndustryData
from .invention import InventionData, InventionError, InventionPlanner, render_invention
from .inventory import Inventory
from .item_info import describe
from .plan import BuildPlanner, PlanError, load_config, write_plan
from .recipe import MAX_MATERIAL_EFFICIENCY, MAX_TIME_EFFICIENCY, RecipeError, RecipeResolver
from .report import render
from .sde_loader import SDEFileError


def _material_efficiency(value: str) -> int:
    try:
        me = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid integer: {value!r}")
    if not 0 <= me <= MAX_MATERIAL_EFFICIENCY:
        raise argparse.ArgumentTypeError(
            f"must be an integer in [0,{MAX_MATERIAL_EFFICIENCY}], got {me}"
        )
    return me


def _time_efficiency(value: str) -> int:
    try:
        te = int(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"invalid integer: {value!r}")
    if not 0 <= te <= MAX_TIME_EFFICIENCY or te % 2:
        raise argparse.ArgumentTypeError(
            f"must be an even integer in [0,{MAX_TIME_EFFICIENCY}], got {te}"
        )
    return te


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="industry.py",
        description="Plan EVE Online industry builds from the Static Data Export.",
    )
    sub = parser.add_subparsers(dest="command", required=True)
    recipe = sub.add_parser("recipe", help="Show the recipe for a product or blueprint")
    recipe.add_argument("name", nargs="+", help="Exact typeName of a product or blueprint")
    recipe.add_argument("--sde", required=True, help="Path to the SDE directory")
    recipe.add_argument("--material-efficiency", "-me", dest="me", type=_material_efficiency,
                        default=0, metavar="ME",
                        help="Blueprint material efficiency, integer in [0,10] (default 0)")
    recipe.add_argument("--time-efficiency", "-te", dest="te", type=_time_efficiency,
                        default=0, metavar="TE",
                        help="Blueprint time efficiency, even integer in [0,20] (default 0)")
    recipe.add_argument("--display-waste", "-waste", dest="waste", action="store_true",
                        help="Show material wasted compared to ME 10")
    invention = sub.add_parser("invention", help="Plan invention / reverse engineering for a product")
    invention.add_argument("name", nargs="+", help="Exact typeName of a Tech II/III product or blueprint")
    invention.add_argument("--sde", required=True, help="Path to the SDE directory")
    invention.add_argument("--skill", type=int, default=5, choices=range(1, 6), metavar="{1-5}",
                           help="Level used for all relevant skills (default 5)")
    plan = sub.add_parser("plan", help="Create a build plan (jobs.csv, materials.csv) for an item")
    plan.add_argument("name", nargs="+", help="Build string, e.g. 'Barrage L 10 None x10'")
    plan.add_argument("--config", required=True, help="YAML build config file")
    plan.add_argument("--sde", required=True, help="Path to the SDE directory")
    plan.add_argument("--output", required=True, help="Directory to write the CSV files to")
    plan.add_argument("--build-all", dest="build_all", action="store_true",
                      help="Also build every buildable component in the tree")
    return parser


def run_recipe(name: str, sde_dir: Path, me: int = 0, te: int = 0, waste: bool = False) -> str:
    inventory = Inventory(sde_dir)
    published = {t.type_id for t in inventory.types.values() if t.published}
    industry = IndustryData(sde_dir, published)
    recipe = RecipeResolver(inventory, industry).resolve(name, me=me, te=te)
    return render(describe(inventory, recipe.product), recipe, show_waste=waste)


def run_invention(name: str, sde_dir: Path, skill: int) -> str:
    inventory = Inventory(sde_dir)
    published = {t.type_id for t in inventory.types.values() if t.published}
    industry = IndustryData(sde_dir, published)
    invention = InventionData(sde_dir, published)
    plan = InventionPlanner(inventory, industry, invention).plan(name, skill)
    return render_invention(describe(inventory, plan.product), plan)


def run_plan(build: str, config_path: Path, sde_dir: Path, output_dir: Path,
             build_all: bool = False) -> None:
    config = load_config(config_path)
    inventory = Inventory(sde_dir)
    published = {t.type_id for t in inventory.types.values() if t.published}
    industry = IndustryData(sde_dir, published)
    invention = InventionData(sde_dir, published)
    planner = BuildPlanner(inventory, industry, invention)
    plan = planner.plan(planner.parse(build), config, build_all=build_all)
    write_plan(plan, inventory, output_dir)


def main(argv: Optional[List[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    name = " ".join(args.name)
    sde_dir = Path(args.sde)
    if not sde_dir.is_dir():
        print(f"Error: SDE directory not found: {sde_dir}", file=sys.stderr)
        return 2
    try:
        if args.command == "recipe":
            print(run_recipe(name, sde_dir, args.me, args.te, args.waste))
        elif args.command == "invention":
            print(run_invention(name, sde_dir, args.skill))
        elif args.command == "plan":
            run_plan(name, Path(args.config), sde_dir, Path(args.output), args.build_all)
        else:
            return 2
    except (RecipeError, InventionError, PlanError, SDEFileError) as exc:
        print(f"Error: {exc}", file=sys.stderr)
        return 1
    return 0
"""Build plans: parses a build string and produces the jobs and materials to buy."""

import csv
import math
import re
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional, Tuple

from . import constants as C
from .industry_data import ActivityKey, IndustryData
from .invention import DECRYPTORS, InventionData, InventionError, InventionPlanner
from .inventory import Inventory
from .models import InvType
from .recipe import MAX_MATERIAL_EFFICIENCY, MAX_TIME_EFFICIENCY
from .sde_loader import load_yaml

MAX_TE_BONUS = 30
MAX_SPLIT_DAYS = 30
DEFAULT_SPLIT_DAYS = 3.0
SECONDS_PER_DAY = 86400
CAPITAL_MARKET_GROUP = "Capital Ships"
CAPITAL_SHIP_GROUPS = frozenset({
    "Capital Industrial Ship", "Carrier", "Dreadnought", "Force Auxiliary", "Freighter",
    "Jump Freighter", "Lancer Dreadnought", "Supercarrier", "Titan",
})
NO_DECRYPTOR = "None"
DECRYPTOR_SUFFIX = " Decryptor"

_JOBS_RE = re.compile(r"^[xX](\d+)$")
_INT_RE = re.compile(r"^\d+$")


class PlanError(Exception):
    """Raised when a build string or config cannot be turned into a build plan."""


@dataclass(frozen=True)
class PlanConfig:
    te_bonus: int = 0
    invention_skill: int = 5
    split_days: float = DEFAULT_SPLIT_DAYS
    component_me: int = MAX_MATERIAL_EFFICIENCY
    component_te: int = MAX_TIME_EFFICIENCY


@dataclass(frozen=True)
class BuildSpec:
    product: InvType
    blueprint_key: ActivityKey
    runs: int
    jobs: int
    me: int = 0
    te: int = 0
    decryptor: Optional[str] = None  # set for invention / reverse engineering
    relic: Optional[str] = None  # set for reverse engineering

    @property
    def invented(self) -> bool:
        return self.decryptor is not None


@dataclass(frozen=True)
class Job:
    name: str
    runs: int
    days: float
    count: int


@dataclass
class BuildPlan:
    jobs: List[Job] = field(default_factory=list)
    # typeID -> quantity to buy
    purchases: Dict[int, int] = field(default_factory=dict)
    # typeID -> surplus left over after the build
    leftovers: Dict[int, int] = field(default_factory=dict)


def load_config(path: Path) -> PlanConfig:
    if not path.is_file():
        raise PlanError(f"Config file not found: {path}")
    raw = load_yaml(path.parent, path.name)
    if not isinstance(raw, dict):
        raise PlanError(f"Config file must be a mapping: {path}")
    te_bonus = _config_int(raw, "te_bonus", 0, 0, MAX_TE_BONUS)
    skill = _config_int(raw, "invention_skill", 5, 1, 5)
    split_days = _config_split_days(raw)
    defaults = raw.get("component_bpo_defaults")
    if defaults is None:
        defaults = {}
    if not isinstance(defaults, dict):
        raise PlanError("Config 'component_bpo_defaults' must be a mapping with 'me' and 'te'")
    me = _config_int(defaults, "me", MAX_MATERIAL_EFFICIENCY, 0, MAX_MATERIAL_EFFICIENCY)
    te = _config_int(defaults, "te", MAX_TIME_EFFICIENCY, 0, MAX_TIME_EFFICIENCY)
    return PlanConfig(te_bonus=te_bonus, invention_skill=skill, split_days=split_days,
                      component_me=me, component_te=te)


def _config_split_days(raw: dict) -> float:
    value = raw.get("split_days", DEFAULT_SPLIT_DAYS)
    if value is None:
        value = DEFAULT_SPLIT_DAYS
    if isinstance(value, bool) or not isinstance(value, (int, float)) or math.isnan(value):
        raise PlanError(f"Config 'split_days' must be a number in (0,{MAX_SPLIT_DAYS}], got {value!r}")
    if not 0 < value <= MAX_SPLIT_DAYS:
        raise PlanError(f"Config 'split_days' must be a number in (0,{MAX_SPLIT_DAYS}], got {value}")
    return float(value)


def _config_int(raw: dict, key: str, default: int, low: int, high: int) -> int:
    value = raw.get(key, default)
    if value is None:
        value = default
    if isinstance(value, bool) or not isinstance(value, (int, float)) or int(value) != value:
        raise PlanError(f"Config '{key}' must be an integer in [{low},{high}], got {value!r}")
    value = int(value)
    if not low <= value <= high:
        raise PlanError(f"Config '{key}' must be an integer in [{low},{high}], got {value}")
    return value


def _decryptor_name(text: str) -> Optional[str]:
    """Canonical decryptor name ('None' included) for user text, or None if unknown."""
    folded = text.lower()
    for name, *_ in DECRYPTORS:
        if folded == name.lower():
            return name
        if name.endswith(DECRYPTOR_SUFFIX) and folded == name[: -len(DECRYPTOR_SUFFIX)].lower():
            return name
    return None


def _positive(text: str, what: str) -> int:
    value = int(text)
    if value < 1:
        raise PlanError(f"{what} must be at least 1, got {value}")
    return value


class BuildPlanner:
    def __init__(self, inventory: Inventory, industry: IndustryData, invention: InventionData):
        self.inventory = inventory
        self.industry = industry
        self.invention = invention

    # --- build string parsing ----------------------------------------------

    def parse(self, build: str) -> BuildSpec:
        tokens = build.split()
        if not tokens:
            raise PlanError("Empty build string")
        jobs = 1
        match = _JOBS_RE.match(tokens[-1])
        if match and len(tokens) > 1:
            jobs = _positive(match.group(1), "Number of jobs")
            tokens = tokens[:-1]

        # Longest item name first, so names containing numbers still resolve.
        for split in range(len(tokens), 0, -1):
            name = " ".join(tokens[:split])
            target = self._production_key(name)
            if target is None:
                continue
            spec = self._interpret(target, tokens[split:], jobs)
            if spec is not None:
                return spec

        for split in range(len(tokens), 0, -1):
            if self.inventory.published_by_name(" ".join(tokens[:split])):
                raise PlanError(f"Cannot interpret build string '{build}'")
        raise PlanError(f"No buildable published item found in build string '{build}'")

    def _production_key(self, name: str) -> Optional[Tuple[InvType, ActivityKey]]:
        candidates = self.inventory.published_by_name(name)
        for item in candidates:
            sources = self.industry.sources_of(item.type_id)
            if sources:
                return item, sources[0]
        # Be lenient and accept a blueprint name as well.
        for item in candidates:
            key = self.industry.blueprint_activity(item.type_id)
            if key is not None:
                product = self.inventory.types.get(self.industry.products[key][0][0])
                if product is not None:
                    return product, key
        return None

    def _interpret(self, target: Tuple[InvType, ActivityKey], rest: List[str],
                   jobs: int) -> Optional[BuildSpec]:
        product, key = target
        if not rest:
            return BuildSpec(product, key, runs=1, jobs=jobs)
        if not _INT_RE.match(rest[0]):
            return None
        runs = _positive(rest[0], "Runs per job")
        rest = rest[1:]
        if not rest:
            return BuildSpec(product, key, runs=runs, jobs=jobs)
        if len(rest) == 2 and all(_INT_RE.match(t) for t in rest):
            me, te = int(rest[0]), int(rest[1])
            if not 0 <= me <= MAX_MATERIAL_EFFICIENCY:
                raise PlanError(f"Material efficiency must be in [0,{MAX_MATERIAL_EFFICIENCY}], got {me}")
            if not 0 <= te <= MAX_TIME_EFFICIENCY:
                raise PlanError(f"Time efficiency must be in [0,{MAX_TIME_EFFICIENCY}], got {te}")
            return BuildSpec(product, key, runs=runs, jobs=jobs, me=me, te=te)
        for split in range(len(rest), 0, -1):
            decryptor = _decryptor_name(" ".join(rest[:split]))
            if decryptor is None:
                continue
            relic = " ".join(rest[split:]) or None
            return BuildSpec(product, key, runs=runs, jobs=jobs, decryptor=decryptor, relic=relic)
        return None

    # --- planning ----------------------------------------------------------

    def plan(self, spec: BuildSpec, config: PlanConfig, build_all: bool = False) -> BuildPlan:
        purchases: Dict[int, int] = defaultdict(int)
        me, te = spec.me, spec.te
        if spec.invented:
            me, te = self._plan_invention(spec, config, purchases)

        blueprint_id, activity_id = spec.blueprint_key
        if activity_id != C.MANUFACTURING:
            me = te = 0

        if not build_all:
            for material_id, qty in self.industry.materials.get(spec.blueprint_key, {}).items():
                purchases[material_id] += _job_material(qty, me, spec.runs) * spec.jobs
            job = self._job(spec.blueprint_key, spec.runs, te, spec.jobs, config)
            return BuildPlan(jobs=[job], purchases=dict(purchases))

        demand: Dict[int, int] = defaultdict(int)
        jobs: Dict[Tuple[str, int], Job] = {}

        def schedule(key: ActivityKey, runs: int, count: int, me: int, te: int) -> None:
            days_per_run = self._days_per_run(key, te, config)
            for job_runs, job_count in split_runs(runs, days_per_run, config.split_days):
                job = self._job(key, job_runs, te, job_count * count, config)
                previous = jobs.get((job.name, job.runs))
                if previous is not None:
                    job = Job(job.name, job.runs, job.days, previous.count + job.count)
                jobs[(job.name, job.runs)] = job
                for material_id, qty in self.industry.materials.get(key, {}).items():
                    amount = _job_material(qty, me, job_runs) * job_count * count
                    if self.industry.is_buildable(material_id):
                        demand[material_id] += amount
                    else:
                        purchases[material_id] += amount

        schedule(spec.blueprint_key, spec.runs, spec.jobs, me, te)

        leftovers: Dict[int, int] = {}
        for type_id in self._consumer_order(spec.blueprint_key):
            needed = demand.get(type_id, 0)
            if needed <= 0:
                continue
            key = self.industry.sources_of(type_id)[0]
            per_run = next(q for p, q in self.industry.products[key] if p == type_id)
            if per_run <= 0:
                raise PlanError(f"'{self.inventory.type_name(type_id)}' cannot be built")
            runs = -(-needed // per_run)
            surplus = runs * per_run - needed
            if surplus:
                leftovers[type_id] = surplus
            component_me, component_te = self._component_efficiency(type_id, key, config)
            schedule(key, runs, 1, component_me, component_te)

        return BuildPlan(jobs=list(jobs.values()), purchases=dict(purchases), leftovers=leftovers)

    def _job(self, key: ActivityKey, runs: int, te: int, count: int, config: PlanConfig) -> Job:
        seconds = self.industry.times.get(key, 0) * runs
        seconds *= (100 - te) * (100 - config.te_bonus) / 10000
        return Job(
            name=self.inventory.type_name(key[0]),
            runs=runs,
            days=round(seconds / SECONDS_PER_DAY, 2),
            count=count,
        )

    def _days_per_run(self, key: ActivityKey, te: int, config: PlanConfig) -> float:
        seconds = self.industry.times.get(key, 0) * ((100 - te) * (100 - config.te_bonus) / 10000)
        return seconds / SECONDS_PER_DAY

    def _component_efficiency(self, type_id: int, key: ActivityKey,
                              config: PlanConfig) -> Tuple[int, int]:
        if key[1] != C.MANUFACTURING:
            return 0, 0
        item = self.inventory.types.get(type_id)
        if item is not None and self._is_t1_capital(item):
            return 0, 0
        return config.component_me, config.component_te

    def _is_t1_capital(self, item: InvType) -> bool:
        if not self.inventory.is_ship(item) or self.inventory.tech_level_of(item) != "Tech I":
            return False
        if self.inventory.group_name_of(item) in CAPITAL_SHIP_GROUPS:
            return True
        return CAPITAL_MARKET_GROUP in (self.inventory.market_group_path(item) or [])

    def _consumer_order(self, root: ActivityKey) -> List[int]:
        """Buildable materials reachable from ``root``, each listed after all of its consumers."""
        order: List[int] = []
        state: Dict[int, int] = {}  # 1 = in progress, 2 = done

        def materials_of(key: ActivityKey) -> List[int]:
            return sorted(m for m in self.industry.materials.get(key, {})
                          if self.industry.is_buildable(m))

        stack: List[Tuple[int, List[int]]] = []
        for material_id in materials_of(root):
            if material_id in state:
                continue
            state[material_id] = 1
            stack.append((material_id, materials_of(self.industry.sources_of(material_id)[0])))
            while stack:
                type_id, pending = stack[-1]
                if pending:
                    child = pending.pop()
                    seen = state.get(child)
                    if seen == 1:
                        raise PlanError(
                            f"Circular recipe involving '{self.inventory.type_name(child)}'")
                    if seen is None:
                        state[child] = 1
                        stack.append((child, materials_of(self.industry.sources_of(child)[0])))
                    continue
                stack.pop()
                state[type_id] = 2
                order.append(type_id)
        order.reverse()
        return order

    def _plan_invention(self, spec: BuildSpec, config: PlanConfig,
                        purchases: Dict[int, int]) -> Tuple[int, int]:
        """Add invention inputs to ``purchases``; return the invented blueprint's (ME, TE)."""
        planner = InventionPlanner(self.inventory, self.industry, self.invention)
        try:
            invention = planner.plan(spec.product.name, config.invention_skill)
        except InventionError as exc:
            raise PlanError(str(exc))
        is_t3 = invention.tech_level == "Tech III"
        if is_t3 and spec.relic is None:
            raise PlanError(f"'{spec.product.name}' is reverse engineered; a relic name is required")
        if not is_t3 and spec.relic is not None:
            raise PlanError(f"'{spec.product.name}' is invented; relics do not apply")

        row = next(
            (r for r in invention.rows
             if r.decryptor == spec.decryptor and (not is_t3 or r.invented_from == spec.relic)),
            None,
        )
        if row is None:
            raise PlanError(f"'{spec.relic}' cannot be used to reverse engineer '{spec.product.name}'")
        if row.probability <= 0 or row.runs <= 0:
            raise PlanError(f"'{spec.product.name}' cannot be invented with these inputs")

        blueprints = math.ceil(spec.runs * spec.jobs / row.runs)
        attempts = math.ceil(blueprints / row.probability - 1e-9)

        source = self._invention_source(spec, is_t3)
        for material_id, qty in self.invention.materials.get(source, {}).items():
            purchases[material_id] += qty * attempts
        if spec.decryptor != NO_DECRYPTOR:
            purchases[self._type_id(spec.decryptor)] += attempts
        if is_t3:
            purchases[source[0]] += attempts
        return row.me, row.te

    def _invention_source(self, spec: BuildSpec, is_t3: bool) -> ActivityKey:
        sources = self.invention.sources_of(spec.blueprint_key[0])
        if is_t3:
            for key in sources:
                if self.inventory.type_name(key[0]) == spec.relic:
                    return key
            raise PlanError(f"'{spec.relic}' cannot be used to reverse engineer '{spec.product.name}'")
        return sources[0]

    def _type_id(self, name: str) -> int:
        candidates = self.inventory.published_by_name(name)
        if not candidates:
            raise PlanError(f"No published item named '{name}' found in the SDE")
        return candidates[0].type_id


def _job_material(per_run: int, me: int, runs: int) -> int:
    """Material needed by a single job, rounded up at the job level."""
    return max(runs, -(-per_run * (100 - me) * runs // 100))


def split_runs(runs: int, days_per_run: float, split_days: float) -> List[Tuple[int, int]]:
    """Split ``runs`` into jobs within the day limit; returns (runs, count) pairs."""
    if runs <= 1 or days_per_run <= 0:
        return [(runs, 1)]
    max_runs = max(1, int(min(float(MAX_SPLIT_DAYS), split_days) // days_per_run))
    if runs <= max_runs:
        return [(runs, 1)]
    t = -(-runs // max_runs)
    base, extra = divmod(runs, t)
    if base + 1 == max_runs and extra > t / 2 and runs // (t + 1) + 1 < max_runs:
        t += 1
        base, extra = divmod(runs, t)
    return [(r, c) for r, c in ((base + 1, extra), (base, t - extra)) if c > 0 and r > 0]


# --- output ----------------------------------------------------------------

def write_plan(plan: BuildPlan, inventory: Inventory, output_dir: Path) -> None:
    output_dir.mkdir(parents=True, exist_ok=True)

    rows = []
    for type_id in set(plan.purchases) | set(plan.leftovers):
        quantity = plan.purchases.get(type_id, 0)
        item = inventory.types.get(type_id)
        name = inventory.type_name(type_id)
        volume = inventory.packaged_volume(item) if item else 0.0
        rows.append((name, quantity, round(quantity * volume, 2), 0, plan.leftovers.get(type_id, 0)))
    rows.sort(key=lambda r: r[0])
    with open(output_dir / "materials.csv", "w", newline="", encoding="utf-8") as fh:
        writer = csv.writer(fh, lineterminator="\n")
        writer.writerow(["name", "to_buy", "buy_volume", "start_amount", "end_amount"])
        writer.writerows(rows)

    jobs = sorted(plan.jobs, key=lambda j: (j.name, j.runs, j.count, j.days))
    with open(output_dir / "jobs.csv", "w", newline="", encoding="utf-8") as fh:
        writer = csv.writer(fh, lineterminator="\n")
        writer.writerow(["name", "runs", "days", "count"])
        for job in jobs:
            writer.writerow([job.name, job.runs, job.days, job.count])

"""Item, group, category, market group and meta (tech level) data."""

from collections import defaultdict
from pathlib import Path
from typing import Dict, List, Optional

from . import constants as C
from .models import Group, InvType, MarketGroup
from .sde_loader import iter_csv, load_yaml, parse_float, parse_int


class Inventory:
    """Indexes the inv* tables and ship volumes from the SDE."""

    def __init__(self, sde_dir: Path):
        self.types: Dict[int, InvType] = {}
        self.types_by_name: Dict[str, List[InvType]] = defaultdict(list)
        self.groups: Dict[int, Group] = {}
        self.categories: Dict[int, str] = {}
        self.market_groups: Dict[int, MarketGroup] = {}
        self.meta_group_of_type: Dict[int, int] = {}
        self.meta_group_names: Dict[int, str] = {}
        self.ship_volumes: Dict[str, float] = {}
        self._load(sde_dir)

    def _load(self, sde_dir: Path) -> None:
        for row in iter_csv(sde_dir, C.INV_TYPES):
            item = InvType(
                type_id=int(row["typeID"]),
                group_id=parse_int(row["groupID"]),
                name=row["typeName"],
                volume=parse_float(row["volume"]),
                published=parse_int(row["published"]) == 1,
                market_group_id=parse_int(row["marketGroupID"]),
            )
            self.types[item.type_id] = item
            if item.published:
                self.types_by_name[item.name].append(item)

        for row in iter_csv(sde_dir, C.INV_GROUPS):
            group = Group(
                group_id=int(row["groupID"]),
                category_id=parse_int(row["categoryID"]),
                name=row["groupName"],
            )
            self.groups[group.group_id] = group

        for row in iter_csv(sde_dir, C.INV_CATEGORIES):
            self.categories[int(row["categoryID"])] = row["categoryName"]

        for row in iter_csv(sde_dir, C.INV_MARKET_GROUPS):
            mg = MarketGroup(
                market_group_id=int(row["marketGroupID"]),
                parent_id=parse_int(row["parentGroupID"]),
                name=row["marketGroupName"],
            )
            self.market_groups[mg.market_group_id] = mg

        for row in iter_csv(sde_dir, C.INV_META_TYPES):
            meta_id = parse_int(row["metaGroupID"])
            if meta_id is not None:
                self.meta_group_of_type[int(row["typeID"])] = meta_id

        for row in iter_csv(sde_dir, C.INV_META_GROUPS):
            self.meta_group_names[int(row["metaGroupID"])] = row["metaGroupName"]

        raw_volumes = load_yaml(sde_dir, C.SHIP_VOLUMES)
        self.ship_volumes = {str(k): float(v) for k, v in raw_volumes.items()}

    # --- lookups -----------------------------------------------------------

    def published_by_name(self, name: str) -> List[InvType]:
        """All published types whose name matches exactly (case-sensitive)."""
        return sorted(self.types_by_name.get(name, []), key=lambda t: t.type_id)

    def type_name(self, type_id: int) -> str:
        item = self.types.get(type_id)
        return item.name if item else str(type_id)

    def group_of(self, item: InvType) -> Optional[Group]:
        return self.groups.get(item.group_id)

    def category_name_of(self, item: InvType) -> str:
        group = self.group_of(item)
        if group is None:
            return "Unknown"
        return self.categories.get(group.category_id, "Unknown")

    def group_name_of(self, item: InvType) -> str:
        group = self.group_of(item)
        return group.name if group else "Unknown"

    def market_group_path(self, item: InvType) -> Optional[List[str]]:
        """Market group names from root to leaf, or None if not on the market."""
        if item.market_group_id is None:
            return None
        path: List[str] = []
        seen = set()
        current = self.market_groups.get(item.market_group_id)
        while current is not None and current.market_group_id not in seen:
            seen.add(current.market_group_id)
            path.append(current.name)
            if current.parent_id is None:
                break
            current = self.market_groups.get(current.parent_id)
        if not path:
            return None
        path.reverse()
        return path

    def tech_level_of(self, item: InvType) -> str:
        meta_id = self.meta_group_of_type.get(item.type_id)
        meta_name = self.meta_group_names.get(meta_id, "") if meta_id else ""
        for level in C.TECH_LEVELS:
            if meta_name == level or meta_name.endswith(" " + level):
                return level
        return C.DEFAULT_TECH_LEVEL

    def is_ship(self, item: InvType) -> bool:
        return self.category_name_of(item) == C.SHIP_CATEGORY_NAME

    def packaged_volume(self, item: InvType) -> float:
        """Packaged volume: ship_volumes.yaml for ships, invTypes otherwise."""
        if self.is_ship(item):
            group_name = self.group_name_of(item)
            if group_name in self.ship_volumes:
                return self.ship_volumes[group_name]
        return item.volume
"""Invention (Tech II) and reverse engineering (Tech III) planning."""

import math
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional, Set, Tuple

from . import constants as C
from .industry_data import ActivityKey, IndustryData
from .inventory import Inventory
from .models import InvType, ItemInfo
from .sde_loader import iter_csv, parse_float, parse_int

SCIENCE_GROUP_NAME = "Science"
ENCRYPTION_SUFFIX = "Encryption Methods"

BASE_ME = 2
BASE_TE = 4

# (name, probability multiplier in % from 100%, runs, ME, TE)
DECRYPTORS: Tuple[Tuple[str, int, int, int, int], ...] = (
    ("None", 0, 0, 0, 0),
    ("Accelerant Decryptor", 20, 1, 2, 10),
    ("Attainment Decryptor", 80, 4, -1, 4),
    ("Augmentation Decryptor", -40, 9, -2, 2),
    ("Optimized Attainment Decryptor", 90, 2, 1, -2),
    ("Optimized Augmentation Decryptor", -10, 7, 2, 0),
    ("Parity Decryptor", 50, 3, 1, -2),
    ("Process Decryptor", 10, 0, 3, 6),
    ("Symmetry Decryptor", 0, 2, 1, 8),
)

# Relic quality -> (base chance, base runs), in display order.
RELIC_QUALITIES: Tuple[Tuple[str, float, int], ...] = (
    ("Intact", 0.26, 20),
    ("Malfunctioning", 0.21, 10),
    ("Wrecked", 0.14, 3),
)


class InventionError(Exception):
    """Raised when no invention plan can be resolved for the requested name."""


@dataclass(frozen=True)
class ProbabilityRow:
    invented_from: Optional[str]
    decryptor: str
    probability: float
    runs: int
    me: int
    te: int


@dataclass
class InventionPlan:
    product: InvType
    tech_level: str
    base_blueprint: Optional[InvType]
    datacores: List[str]
    required_per_run: int
    skills: List[str]
    time_minutes: int
    rows: List[ProbabilityRow] = field(default_factory=list)


class InventionData:
    """Indexes the invention / reverse engineering rows of the industry tables."""

    def __init__(self, sde_dir: Path, published_type_ids: Set[int]):
        self.times: Dict[ActivityKey, int] = {}
        # blueprint/product made by invention -> list of (source, activity)
        self.sources: Dict[int, List[ActivityKey]] = defaultdict(list)
        # (source, activity, product) -> runs / probability
        self.quantities: Dict[Tuple[int, int, int], int] = {}
        self.probabilities: Dict[Tuple[int, int, int], float] = {}
        # (source, activity) -> {materialTypeID: quantity}
        self.materials: Dict[ActivityKey, Dict[int, int]] = defaultdict(dict)
        # (source, activity) -> {skillID: level}
        self.skills: Dict[ActivityKey, Dict[int, int]] = defaultdict(dict)
        self._load(sde_dir, published_type_ids)

    def _load(self, sde_dir: Path, published: Set[int]) -> None:
        wanted = set(C.INVENTION_ACTIVITIES)

        for row in iter_csv(sde_dir, C.INDUSTRY_ACTIVITY):
            key = (int(row["typeID"]), int(row["activityID"]))
            if key[1] in wanted:
                self.times[key] = parse_int(row["time"]) or 0

        for row in iter_csv(sde_dir, C.INDUSTRY_PRODUCTS):
            key = (int(row["typeID"]), int(row["activityID"]))
            if key[1] not in wanted or key[0] not in published:
                continue
            product_id = int(row["productTypeID"])
            self.sources[product_id].append(key)
            self.quantities[(key[0], key[1], product_id)] = parse_int(row["quantity"]) or 0

        for row in iter_csv(sde_dir, C.INDUSTRY_PROBABILITIES):
            activity_id = int(row["activityID"])
            if activity_id not in wanted:
                continue
            triple = (int(row["typeID"]), activity_id, int(row["productTypeID"]))
            self.probabilities[triple] = parse_float(row["probability"])

        for row in iter_csv(sde_dir, C.INDUSTRY_MATERIALS):
            key = (int(row["typeID"]), int(row["activityID"]))
            if key[1] not in wanted:
                continue
            material_id = int(row["materialTypeID"])
            bucket = self.materials[key]
            bucket[material_id] = bucket.get(material_id, 0) + (parse_int(row["quantity"]) or 0)

        for row in iter_csv(sde_dir, C.INDUSTRY_SKILLS):
            key = (int(row["typeID"]), int(row["activityID"]))
            if key[1] not in wanted:
                continue
            self.skills[key][int(row["skillID"])] = parse_int(row["level"]) or 0

    def sources_of(self, blueprint_id: int) -> List[ActivityKey]:
        return sorted(set(self.sources.get(blueprint_id, [])), key=lambda k: (k[0], k[1]))


def relic_quality(name: str) -> Optional[int]:
    """Index into RELIC_QUALITIES for a relic name, or None if it is not a relic."""
    words = name.split()
    for index, (quality, _, _) in enumerate(RELIC_QUALITIES):
        if quality in words:
            return index
    return None


def success_chance(base: float, science_levels: List[int], encryption_levels: List[int],
                   multiplier: int) -> float:
    skill_factor = 1.0
    for level in science_levels:
        skill_factor += level / 30
    for level in encryption_levels:
        skill_factor += level / 40
    chance = base * skill_factor * (1 + multiplier / 100)
    return min(1.0, max(0.0, chance))


class InventionPlanner:
    def __init__(self, inventory: Inventory, industry: IndustryData, invention: InventionData):
        self.inventory = inventory
        self.industry = industry
        self.invention = invention

    # --- resolution --------------------------------------------------------

    def _resolve_target(self, name: str) -> Tuple[InvType, int, List[ActivityKey]]:
        """Return (product, invented blueprint ID, invention sources)."""
        candidates = self.inventory.published_by_name(name)
        if not candidates:
            raise InventionError(f"No published item named '{name}' found in the SDE")

        # Interpreted as an invented blueprint.
        for item in candidates:
            sources = self.invention.sources_of(item.type_id)
            if not sources:
                continue
            key = (item.type_id, C.MANUFACTURING)
            products = self.industry.products.get(key)
            if products:
                return self._require_type(products[0][0]), item.type_id, sources

        # Interpreted as a product whose blueprint is invented.
        for item in candidates:
            for blueprint_id, activity_id in self.industry.sources_of(item.type_id):
                if activity_id != C.MANUFACTURING:
                    continue
                sources = self.invention.sources_of(blueprint_id)
                if sources:
                    return item, blueprint_id, sources

        raise InventionError(f"'{name}' cannot be obtained through invention or reverse engineering")

    def _require_type(self, type_id: int) -> InvType:
        item = self.inventory.types.get(type_id)
        if item is None:
            raise InventionError(f"Type {type_id} referenced by industry data is missing")
        return item

    # --- planning ----------------------------------------------------------

    def plan(self, name: str, skill_level: int) -> InventionPlan:
        product, blueprint_id, sources = self._resolve_target(name)

        tech_level = self.inventory.tech_level_of(product)
        if tech_level not in ("Tech II", "Tech III"):
            relic_based = any(
                relic_quality(self.inventory.type_name(s)) is not None
                or a == C.REVERSE_ENGINEERING
                for s, a in sources
            )
            tech_level = "Tech III" if relic_based else "Tech II"
        is_t3 = tech_level == "Tech III"

        if is_t3:
            used = sorted(sources, key=lambda k: self._relic_sort_key(k[0]))
        else:
            used = sources[:1]

        datacore_qty: Dict[int, int] = {}
        skill_levels: Dict[int, int] = {}
        for key in used:
            for material_id, qty in self.invention.materials.get(key, {}).items():
                datacore_qty[material_id] = max(datacore_qty.get(material_id, 0), qty)
            skill_levels.update(self.invention.skills.get(key, {}))

        datacores = sorted((self.inventory.type_name(m) for m in datacore_qty), key=_name_key)
        required_per_run = max(datacore_qty.values()) if datacore_qty else 0
        skills = sorted((self.inventory.type_name(s) for s in skill_levels), key=_name_key)

        science_levels: List[int] = []
        encryption_levels: List[int] = []
        for skill_id in sorted(skill_levels, key=lambda s: _name_key(self.inventory.type_name(s))):
            skill = self.inventory.types.get(skill_id)
            if skill is None:
                continue
            if skill.name.endswith(ENCRYPTION_SUFFIX):
                encryption_levels.append(skill_level)
            elif self.inventory.group_name_of(skill) == SCIENCE_GROUP_NAME:
                science_levels.append(skill_level)

        seconds = self.invention.times.get(used[0], 0)

        rows: List[ProbabilityRow] = []
        for source_id, activity_id in used:
            triple = (source_id, activity_id, blueprint_id)
            source_name = self.inventory.type_name(source_id)
            base_chance = self.invention.probabilities.get(triple, 0.0)
            base_runs = self.invention.quantities.get(triple, 0)
            if is_t3:
                quality = relic_quality(source_name)
                if quality is not None:
                    _, base_chance, base_runs = RELIC_QUALITIES[quality]
            for decryptor, multiplier, runs, me, te in DECRYPTORS:
                rows.append(ProbabilityRow(
                    invented_from=source_name if is_t3 else None,
                    decryptor=decryptor,
                    probability=success_chance(base_chance, science_levels, encryption_levels, multiplier),
                    runs=base_runs + runs,
                    me=BASE_ME + me,
                    te=BASE_TE + te,
                ))

        return InventionPlan(
            product=product,
            tech_level=tech_level,
            base_blueprint=None if is_t3 else self._require_type(used[0][0]),
            datacores=datacores,
            required_per_run=required_per_run,
            skills=skills,
            time_minutes=math.ceil(seconds / 60),
            rows=rows,
        )

    def _relic_sort_key(self, source_id: int):
        name = self.inventory.type_name(source_id)
        quality = relic_quality(name)
        rank = quality if quality is not None else len(RELIC_QUALITIES)
        return (rank, name.lower(), name, source_id)


def _name_key(name: str):
    return (name.lower(), name)


# --- rendering -------------------------------------------------------------

def render_invention(info: ItemInfo, plan: InventionPlan) -> str:
    market = " > ".join(info.market_group_path) if info.market_group_path else "None"
    lines: List[str] = [
        f"ITEM: {info.name} ({info.type_id})",
        f"Group: {info.category_name} > {info.group_name}",
        f"Market Group: {market}",
        f"Tech Level: {plan.tech_level}",
        "",
        "Invention:",
    ]
    if plan.base_blueprint is not None:
        lines.append(f"Base: {plan.base_blueprint.name} ({plan.base_blueprint.type_id})")
    lines += [
        f"Datacores: {', '.join(plan.datacores)}",
        f"Required Per Run: {plan.required_per_run}",
        f"Skills: {', '.join(plan.skills)}",
        f"Time: {plan.time_minutes}",
        "Probabilities:",
    ]
    is_t3 = plan.tech_level == "Tech III"
    if is_t3:
        lines += [
            "| Invented From                | Decryptor                       | Probability | Runs | ME | TE |",
            "|------------------------------|---------------------------------|-------------|------|----|----|",
        ]
    else:
        lines += [
            "| Decryptor                       | Probability | Runs | ME | TE |",
            "|---------------------------------|-------------|------|----|----|",
        ]
    for row in plan.rows:
        cells = f"| {row.decryptor:<32}| {row.probability * 100:.2f}".ljust(48)
        cells += f"| {row.runs:<5}| {row.me:<3}| {row.te:<3}|"
        if is_t3:
            cells = f"| {row.invented_from:<29}" + cells
        lines.append(cells)
    return "\n".join(lines)
"""Builds the descriptive header information for an item."""

from .inventory import Inventory
from .models import InvType, ItemInfo


def format_volume(volume: float, is_ship: bool) -> str:
    """Ships (packaged) use two decimals; other items keep their natural precision."""
    if is_ship:
        return f"{volume:.2f}"
    text = repr(float(volume))
    if "e" in text or "E" in text:
        text = format(volume, "f").rstrip("0")
        if text.endswith("."):
            text += "0"
    return text


def describe(inventory: Inventory, item: InvType) -> ItemInfo:
    is_ship = inventory.is_ship(item)
    return ItemInfo(
        type_id=item.type_id,
        name=item.name,
        category_name=inventory.category_name_of(item),
        group_name=inventory.group_name_of(item),
        market_group_path=inventory.market_group_path(item),
        tech_level=inventory.tech_level_of(item),
        volume_text=format_volume(inventory.packaged_volume(item), is_ship),
    )

"""Blueprint activities, products and materials from the industry tables."""

from collections import defaultdict
from pathlib import Path
from typing import Dict, List, Optional, Set, Tuple

from . import constants as C
from .sde_loader import iter_csv, parse_int

ActivityKey = Tuple[int, int]  # (blueprintTypeID, activityID)


class IndustryData:
    """Indexes manufacturing and reaction data, restricted to published blueprints."""

    def __init__(self, sde_dir: Path, published_type_ids: Set[int]):
        self.activity_names: Dict[int, str] = {}
        self.times: Dict[ActivityKey, int] = {}
        # (blueprint, activity) -> list of (productTypeID, quantity)
        self.products: Dict[ActivityKey, List[Tuple[int, int]]] = defaultdict(list)
        # productTypeID -> list of (blueprint, activity)
        self.sources: Dict[int, List[ActivityKey]] = defaultdict(list)
        # (blueprint, activity) -> {materialTypeID: quantity}
        self.materials: Dict[ActivityKey, Dict[int, int]] = defaultdict(dict)
        self._load(sde_dir, published_type_ids)

    def _load(self, sde_dir: Path, published: Set[int]) -> None:
        wanted = set(C.PRODUCTION_ACTIVITIES)

        for row in iter_csv(sde_dir, C.RAM_ACTIVITIES):
            self.activity_names[int(row["activityID"])] = row["activityName"]

        for row in iter_csv(sde_dir, C.INDUSTRY_ACTIVITY):
            key = (int(row["typeID"]), int(row["activityID"]))
            if key[1] in wanted:
                self.times[key] = parse_int(row["time"]) or 0

        for row in iter_csv(sde_dir, C.INDUSTRY_PRODUCTS):
            key = (int(row["typeID"]), int(row["activityID"]))
            if key[1] not in wanted or key[0] not in published:
                continue
            product_id = int(row["productTypeID"])
            self.products[key].append((product_id, parse_int(row["quantity"]) or 0))
            self.sources[product_id].append(key)

        for row in iter_csv(sde_dir, C.INDUSTRY_MATERIALS):
            key = (int(row["typeID"]), int(row["activityID"]))
            if key[1] not in wanted:
                continue
            material_id = int(row["materialTypeID"])
            quantity = parse_int(row["quantity"]) or 0
            bucket = self.materials[key]
            bucket[material_id] = bucket.get(material_id, 0) + quantity

    def activity_name(self, activity_id: int) -> str:
        return self.activity_names.get(activity_id, str(activity_id))

    def blueprint_activity(self, blueprint_id: int) -> Optional[ActivityKey]:
        """The production activity a published blueprint performs, if any."""
        for activity_id in C.PRODUCTION_ACTIVITIES:
            key = (blueprint_id, activity_id)
            if self.products.get(key):
                return key
        return None

    def sources_of(self, product_id: int) -> List[ActivityKey]:
        """Published (blueprint, activity) pairs producing a type, sorted deterministically."""
        order = {a: i for i, a in enumerate(C.PRODUCTION_ACTIVITIES)}
        return sorted(self.sources.get(product_id, []), key=lambda k: (order[k[1]], k[0]))

    def is_buildable(self, type_id: int) -> bool:
        return bool(self.sources.get(type_id))
"""Low-level readers for the raw SDE files (bz2-compressed CSVs and YAML)."""

import bz2
import csv
import io
from pathlib import Path
from typing import Dict, Iterator

import yaml


class SDEFileError(Exception):
    """Raised when a required SDE file is missing or unreadable."""


def iter_csv(sde_dir: Path, filename: str) -> Iterator[Dict[str, str]]:
    """Yield each row of a bz2-compressed CSV file as a dict."""
    path = sde_dir / filename
    if not path.is_file():
        raise SDEFileError(f"Missing SDE file: {path}")
    with bz2.open(path, "rb") as raw:
        text = io.TextIOWrapper(raw, encoding="utf-8", newline="")
        yield from csv.DictReader(text)


def load_yaml(sde_dir: Path, filename: str):
    """Load a plain YAML file."""
    path = sde_dir / filename
    if not path.is_file():
        raise SDEFileError(f"Missing SDE file: {path}")
    with open(path, "r", encoding="utf-8") as fh:
        return yaml.safe_load(fh) or {}


def parse_int(value: str):
    """Parse an integer field, returning None for empty / 'None' values."""
    if value is None:
        return None
    value = value.strip()
    if value == "" or value == "None":
        return None
    return int(float(value))


def parse_float(value: str, default: float = 0.0) -> float:
    """Parse a float field, returning ``default`` for empty / 'None' values."""
    if value is None:
        return default
    value = value.strip()
    if value == "" or value == "None":
        return default
    return float(value)

